#!/usr/bin/env python3
"""Generate dashboard ATLAS labels from the scanner's supported vocabulary."""

from __future__ import annotations

import argparse
import json
from pathlib import Path

from agent_bom.atlas import ATLAS_TECHNIQUES

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "ui/lib/atlas-labels.generated.ts"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    content = (
        "// Generated by python scripts/generate_atlas_labels.py; do not edit.\n"
        "// Label vocabulary is not detection coverage.\n"
        "export const ATLAS_LABELS: Record<string, string> = " + json.dumps(ATLAS_TECHNIQUES, indent=2, sort_keys=True) + ";\n"
    )
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text() != content:
            print("ATLAS UI labels are stale; run python scripts/generate_atlas_labels.py")
            return 1
    else:
        OUTPUT.write_text(content)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
